def clean(df):
    d = df.copy()
    # Price written as text with $ signs -> numeric
    d["Price"] = pd.to_numeric(d["Price"].astype(str).str.replace(r"[$,]", "", regex=True), errors="coerce")
    d["Quantity"] = pd.to_numeric(d["Quantity"], errors="coerce")
    # Region label variants -> canonical allowed values
    canon = {"north": "North", "south": "South", "east": "East", "west": "West"}
    def fix_region(x):
        s = str(x).strip().lower()
        if s in canon:
            return canon[s]
        if s.startswith("nort"):
            return "North"
        if s.startswith("sout"):
            return "South"
        if s.startswith("east"):
            return "East"
        if s.startswith("west") or s.startswith("wst"):
            return "West"
        return None
    d["Region"] = d["Region"].map(fix_region)
    # Recompute Revenue from Quantity * Price
    d["Revenue"] = d["Quantity"] * d["Price"]
    return d

def answer(df):
    d = df[df["Category"] == "Electronics"]
    g = d.groupby("Region")["Revenue"].sum()
    return {str(k): float(v) for k, v in g.items() if pd.notna(k)}
